// swift-tools-version: 6.2
// WortCore: the parts of Wort with no UI, so `swift test` runs them on their own.
// The iPhone and Mac apps (and the share extension) are built from Wort.xcodeproj,
// generated by xcodegen from project.yml; they link this package.
import PackageDescription

let package = Package(
    name: "Wort",
    platforms: [.iOS(.v26), .macOS(.v26)],
    products: [
        .library(name: "WortCore", targets: ["WortCore"]),
    ],
    targets: [
        .target(name: "WortCore", resources: [.process("Resources")]),
        .testTarget(name: "WortCoreTests", dependencies: ["WortCore"],
                    resources: [.copy("Fixtures")]),
    ]
)
